R=[
("शहद और संतरे के साथ ब्रेज़्ड गाजर",
"मधुमेह के अनुकूल इस रेसिपी से गाजर में प्राकृतिक मिठास जोड़ें। इस स्वादिष्ट साइड डिश में ताज़े संतरे के नींबू-वर्गीय फलों की चमकदार बौछार मिट्टी जैसी खुशबू वाले जीरे के साथ जुड़ती है।",
"6","1/2 कप",
["2 बड़े चम्मच ऑलिव ऑयल","1 पाउंड गाजर (छिली और गोल टुकड़ों में कटी हुई)","2 बड़े चम्मच शहद","1 संतरा (छिलका और रस)","1/2 कप कम सोडियम वाला सब्ज़ी का शोरबा","1 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच नमक","1 बड़ा चम्मच सूखा थाइम (कटा हुआ)"],
["एक बड़ी कड़ाही में मध्यम आँच पर ऑलिव ऑयल गरम करें।","कटी हुई गाजर कड़ाही में डालें और 2–3 मिनट भूनें।","संतरे का छिलका कद्दूकस करें और रस निचोड़ें।","एक छोटे कटोरे में शहद, संतरे का छिलका, संतरे का रस, सब्ज़ी का शोरबा, पिसा जीरा, नमक और काली मिर्च को फेंटकर मिलाएँ।","शहद और संतरे का मिश्रण कड़ाही में गाजर के ऊपर डालें।","मिश्रण को धीमी आँच पर उबालें, फिर आँच कम कर दें।","कड़ाही को ढक दें और गाजर को बीच-बीच में चलाते हुए 15–20 मिनट, या नरम होने तक ब्रेज़ होने दें।","जब गाजर नरम हो जाए और तरल कम हो जाए, तो उन्हें परोसने की डिश में निकालें।","चाहें तो ताज़ी थाइम की पत्तियों से सजाएँ।"],[]),
("रेड वाइन विनेग्रेट के साथ साइड ग्रीक सलाद",
"यह एक सरल, नमकीन साइड सलाद है जो लगभग किसी भी मुख्य व्यंजन के साथ बढ़िया लगता है जब आपको अपने भोजन में और सब्ज़ियाँ जोड़नी हों। दोगुनी मात्रा बनाएँ और कुछ हिस्सा किसी और भोजन के लिए बचा लें। ड्रेसिंग को अलग रखकर रखें ताकि यह फ्रिज में 3 दिन तक चल सके। अपनी प्लेट पूरी करें: पौधों पर आधारित भूमध्यसागरीय भोजन के लिए इस सलाद को सफ़ेद बीन्स के साथ स्लो-कुकर रैटाटुइ जैसे शाकाहारी मुख्य व्यंजन के साथ जोड़ें।",
"4","1 कप",
["3 कप रोमेन लेट्यूस (कटा हुआ)","1/4 मध्यम लाल प्याज़ (पतला कटा हुआ)","1/2 मध्यम खीरा (अर्धचंद्र आकार में कटा हुआ)","1 मध्यम टमाटर (आधा करके पतला कटा हुआ)","लगभग 8 कलामाता जैतून (गुठली निकाले हुए)","1/4 कप रेड वाइन विनेग्रेट"],
["लेट्यूस, प्याज़, खीरा, टमाटर और जैतून को एक बड़े कटोरे में डालें। मिलाने के लिए चलाएँ। रेड वाइन विनेग्रेट ऊपर से डालें और सब्ज़ियों पर बराबर परत चढ़ाने के लिए फिर से मिलाएँ।"],[]),
("सोया दूध का दही, सादा",
"सोया दही, सादा, की पोषण संबंधी जानकारी",
"1","5.3 औंस",
["5 1/3 औंस सोया दूध का दही, सादा"],[],[]),
("बटरनट स्क्वैश और काबुली चनों के साथ करी क्विनोआ",
"करी पाउडर, काबुली चने और स्क्वैश भारतीय व्यंजनों का पारंपरिक मेल हैं। इस रेसिपी में, करी के स्वाद को निखारने और मिश्रण में स्वागत योग्य बनावट जोड़ने के लिए, मैंने ताज़ा अदरक, रेड वाइन विनेगर, नींबू का छिलका और हरा धनिया भी डाला है, साथ ही मेवे जैसे स्वाद वाला क्विनोआ और कुरकुरे कद्दू के बीज भी। यह व्यंजन पतझड़ में सबसे अच्छा बनता है जब किसान बाज़ार में बटरनट स्क्वैश के ढेर उपलब्ध होते हैं, लेकिन अगर आपको गर्मी के महीनों में यह मसालेदार सलाद खाने का मन हो, तो बेझिझक इसके बजाय जमा हुआ (और पिघलाया हुआ) स्क्वैश इस्तेमाल करें।",
"10","1/2 कप",
["1 छोटा बटरनट स्क्वैश (छिला, बीज निकाला हुआ और क्यूब्स में कटा हुआ (2–3 कप))","2 बड़े चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल (बाँटकर उपयोग करें)","1/2 छोटा चम्मच महीन समुद्री नमक (बाँटकर उपयोग करें)","1/4 छोटा चम्मच ताज़ी पिसी काली मिर्च (बाँटकर उपयोग करें)","1 कप बिना पका क्विनोआ","2 1/4 कप पानी","1 1/2 छोटे चम्मच करी पाउडर","1 1/2 छोटे चम्मच पिसा जीरा","2 छोटे चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","1 छोटा चम्मच सरसों का पाउडर","1 (16 औंस) कैन काबुली चने (छोले) (धोए और छाने हुए)","2 बड़े चम्मच रेड वाइन विनेगर","1 छोटा चम्मच नींबू का छिलका (ताज़ा कद्दूकस किया हुआ)","1/4 कप कद्दू के बीज","1/4 कप ताज़ा हरा धनिया (कटा हुआ)"],
["ओवन को 400°F पर पहले से गरम करें। किनारे वाली बेकिंग शीट पर चर्मपत्र कागज़ बिछाएँ।","एक मध्यम कटोरे में स्क्वैश को 1 बड़े चम्मच ऑलिव ऑयल, 1/4 छोटा चम्मच नमक और 1/8 छोटा चम्मच काली मिर्च के साथ मिलाएँ। बराबर परत चढ़ाने के लिए मिलाएँ। स्क्वैश को तैयार बेकिंग शीट पर फैलाएँ। लगभग 15 मिनट बेक करें, चलाएँ, फिर नरम होने तक 15 मिनट और बेक करें। बेकिंग शीट को ओवन से निकालें और एक तरफ़ रख दें।","जब स्क्वैश ओवन में हो, तब एक मध्यम सॉसपैन में मध्यम-तेज़ आँच पर क्विनोआ, पानी, करी पाउडर, जीरा, अदरक और सरसों का पाउडर मिलाएँ। मिश्रण को उबालें, फिर आँच धीमी करें, ढक दें और तरल के सोखे जाने तक, लगभग 12–15 मिनट धीमी आँच पर पकाएँ। ढकने के बाद न चलाएँ।","एक बड़े कटोरे में पका हुआ क्विनोआ, भुना हुआ स्क्वैश, बचा हुआ 1 बड़ा चम्मच ऑलिव ऑयल, काबुली चने, रेड वाइन विनेगर, नींबू का छिलका, कद्दू के बीज और हरा धनिया मिलाएँ। बचा हुआ नमक और काली मिर्च डालें। गरम या कमरे के तापमान पर परोसें।"],[]),
("ग्रिल्ड सब्ज़ियों का पास्ता सलाद",
"इस साइड डिश को भोजन बनाने के लिए, इसमें कटा हुआ पका चिकन या झींगे डालें।",
"10","1 कप",
["2 कप साबुत गेहूँ की रोटिनी या पेने पास्ता (बिना पकी)","1 पाउंड शतावरी (सिरे कटे हुए)","2 मध्यम तोरी/ज़ुकीनी (लंबाई में 1/4 इंच मोटी कटी हुई)","1 छोटा बैंगन (छिला और लंबाई में 1/2 इंच मोटा कटा हुआ)","1 बड़ी लाल शिमला मिर्च (बीज निकाली और लंबाई में आधी कटी हुई)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 1/2 बड़े चम्मच ऑलिव ऑयल","1 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच सूखा ओरेगानो (कटा हुआ)","1/2 छोटा चम्मच कोशर नमक (वैकल्पिक)","1/2 छोटा चम्मच काली मिर्च"],
["घर के अंदर या बाहर का ग्रिल तैयार करें।","पास्ता को पैकेट के निर्देशों के अनुसार, नमक डाले बिना पकाएँ।","सभी सब्ज़ियों पर कुकिंग स्प्रे लगाएँ और बार-बार पलटते हुए 7-10 मिनट ग्रिल करें।","सब्ज़ियों को ग्रिल से निकालें और छोटे टुकड़ों में काटें।","पके हुए पास्ता का पानी निथारें और तुरंत कटी हुई ग्रिल्ड सब्ज़ियाँ गरम पास्ता में डालें। ऑलिव ऑयल, लहसुन, ओरेगानो, नमक (वैकल्पिक) और पिसी काली मिर्च डालें और परत चढ़ाने के लिए अच्छी तरह चलाएँ। इस व्यंजन को गरम या ठंडा परोसें।"],[]),
("ब्लूबेरी के साथ ग्रीक योगर्ट वनीला मूस",
"ग्रीक योगर्ट वनीला मूस पारंपरिक मूस का हल्का विकल्प है, जिसमें ग्रीक योगर्ट की खट्टी भरपूरता वनीला के मीठे और आरामदायक स्वादों के साथ मिलती है। एक सुंदर मिठाई के लिए परोसने से पहले कुछ ताज़ी ब्लूबेरी डालें।",
"4","1/2 कप मूस + 1/4 कप ब्लूबेरी",
["2 कप सादा बिना वसा वाला ग्रीक योगर्ट","1/3 कप 1% दूध","2 बड़े चम्मच हेवी क्रीम","1/4 कप चीनी रहित मेपल-प्रकार का सिरप (शून्य कैलोरी)","2 छोटे चम्मच वनीला एक्सट्रैक्ट","1 कप ब्लूबेरी"],
["एक मिक्सिंग बाउल में बिना वसा वाला ग्रीक योगर्ट, दूध, हेवी क्रीम, मेपल सिरप और वनीला एक्सट्रैक्ट मिलाएँ।","हैंड मिक्सर का उपयोग करें और मिश्रण के अच्छी तरह मिलकर फूलने तक फेंटें।","ग्रीक योगर्ट के मिश्रण को 4 सर्विंग कप या गिलासों में बाँटें।","मूस को जमने के लिए कम से कम 2 घंटे फ्रिज में ठंडा करें।","परोसने से पहले हर एक के ऊपर 1/4 कप ताज़ी ब्लूबेरी डालें।"],[]),
("ओवन में बेक किए मदुरोस (मीठे केले/प्लांटेन)",
"यह शायद बहुत बड़ी रेसिपी न लगे, लेकिन तले हुए मीठे प्लांटेन अधिकांश लैटिन देशों में एक प्रमुख साइड डिश हैं। आम तौर पर दोपहर के भोजन में चावल, स्टेक और बीन्स के साथ मदुरोस का साइड होता है। इन्हें बेक करना तलने से कहीं आसान है और इससे इनकी सारी प्राकृतिक शर्करा उभरकर आती है। यहाँ राज़ यह है कि बहुत पके प्लांटेन का उपयोग करें। प्लांटेन कार्बोहाइड्रेट के बेहतर स्रोतों में से एक हैं, क्योंकि ये पोटैशियम से भरपूर हैं, पाचन को नियंत्रित करने और रोग प्रतिरोधक क्षमता बढ़ाने में मदद कर सकते हैं, और भी बहुत कुछ। तो आगे बढ़ें और सीमित मात्रा में इनका आनंद लें।",
"6","लगभग 4 स्लाइस",
["3 स्प्रे नॉनस्टिक कुकिंग स्प्रे","2 (कुल लगभग 1 पाउंड) बहुत पके प्लांटेन (काले छिलके वाले) (छिले हुए और 1/2 इंच मोटे तिरछे स्लाइस में कटे हुए)"],
["ओवन को 400ºF पर पहले से गरम करें। एक छोटे बेकिंग पैन में फ़ॉइल बिछाएँ। फ़ॉइल पर नॉनस्टिक स्प्रे करें।","प्लांटेन के स्लाइस को बेकिंग पैन पर एक परत में रखें और ऊपरी हिस्से पर नॉनस्टिक स्प्रे करें। नरम होने तक, लगभग 12 मिनट बेक करें।","स्लाइस को पलटें, उन पर नॉनस्टिक स्प्रे करें, और प्लांटेन के नरम होने तक, लगभग 6 मिनट और बेक करें।"],[]),
("चीज़ी नमकीन ओटमील",
"ये नमकीन ओट्स इतने अच्छे हैं कि आप इन्हें नाश्ते, दोपहर और रात के खाने, तीनों में खाना चाहेंगे! मधुमेह के अनुकूल यह रेसिपी ओटमील की बहुमुखी प्रतिभा को नए और ताज़े तरीके से दिखाती है। मलाईदार एवोकाडो, अंडे और चीज़ शिमला मिर्च और गाजर के साथ इस पेट भरने वाले एक कटोरे के भोजन में मिलते हैं।",
"6","3/4 कप ओट्स + ~1/2 कप पके अंडे + 1/6 एवोकाडो",
["1 बड़ा चम्मच +2 छोटे चम्मच ऑलिव ऑयल (बाँटकर)","1 कप स्टील कट ओट्स","4 कप पानी","1/8 छोटा चम्मच नमक","1/2 कप गाजर (कद्दूकस की हुई)","1 मध्यम लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","1/2 कप कम वसा वाला कॉटेज चीज़ (बिना नमक का)","1 1/2 कप अंडे का विकल्प","1/8 छोटा चम्मच काली मिर्च","1 बड़ा एवोकाडो (चार भागों में कटा हुआ)","1 छोटा चम्मच श्रीराचा","2 बड़े चम्मच मॉन्टेरी जैक या पेपर जैक चीज़ (कम वसा वाला, कद्दूकस किया हुआ)"],
["मध्यम आँच पर 1 बड़ा चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल गरम करें। ओट्स डालें और खुशबू आने तक, लगभग 2-3 मिनट चलाएँ। पानी और नमक डालें और मध्यम-धीमी आँच पर 20 मिनट पकाएँ, बीच-बीच में चलाते हुए, जब तक अधिकांश तरल सोख न लिया जाए।","जब ओट्स पक रहे हों, तब एक मध्यम कड़ाही में 1 छोटा चम्मच ऑलिव ऑयल गरम करें। गाजर डालें और","ओट्स को आँच से उतारें और गाजर, शिमला मिर्च और कॉटेज चीज़ मिलाएँ, अच्छी तरह चलाएँ।","जिस कड़ाही में सब्ज़ियाँ पकाई थीं उसमें बचा हुआ छोटा चम्मच ऑलिव ऑयल डालें और मध्यम आँच पर गरम करें। अंडे का विकल्प और काली मिर्च डालें और अंडों के हल्का और फूला होने तक चलाते हुए पकाएँ। आँच से उतार लें।","3/4 कप ओटमील का मिश्रण एक कटोरे में रखें। ऊपर 1/2 कप अंडे और एवोकाडो के कुछ स्लाइस रखें। श्रीराचा की बूँदें डालें और थोड़ा मॉन्टेरी जैक चीज़ छिड़कें।"],[]),
("मेसन जार फ़ो सूप",
"अगर आप झटपट, साथ ले जाने लायक दोपहर का भोजन ढूँढ रहे हैं जो बिल्कुल साधारण नहीं है, तो यह मेसन जार फ़ो सूप आपका मन तृप्त कर देगा। समय बचाने के लिए, आप इनमें से कुछ जार पहले से बनाकर पूरे सप्ताह उनका आनंद ले सकते हैं। इस सूप के लिए इंस्टेंट राइस नूडल्स देखें। अगर आपको इंस्टेंट नूडल्स न मिलें, तो सामान्य राइस नूडल्स को आधा उबालें (थोड़ी देर उबालें) और जार में पैक करने से पहले उन पर थोड़ा कुकिंग स्प्रे करें। बुइलॉन की जगह, बिना नमक मिलाए बीफ़ शोरबा का उपयोग करें।",
"1","3 औंस बीफ़ + 2 कप सब्ज़ियाँ + 1 औंस नूडल्स + 1 कप शोरबा",
["1 छोटा चम्मच सोडियम रहित बीफ़ बुइलॉन","1 छोटा चम्मच ताज़ा अदरक (कटा हुआ)","1 औंस इंस्टेंट राइस नूडल्स","3 औंस दुबला स्टेक (पका हुआ, पतली पट्टियों में कटा हुआ)","1/2 कप क्रेमिनी (बेबी बेला) मशरूम (कटे हुए)","1/4 कप हरी पत्ता गोभी (पतली कटी हुई)","1/4 कप लाल शिमला मिर्च (पतली कटी हुई)","1/4 कप गाजर (कद्दूकस की हुई)","2 बड़े चम्मच ताज़ी छिली एडामामे","1 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ)","2 बड़े चम्मच ताज़ा हरा धनिया","1 छोटा चम्मच सोया सॉस","1 छोटा चम्मच ताज़ा नींबू का रस","1 कप उबलता पानी"],
["कसकर बंद होने वाले ढक्कन वाला एक बड़ा (24 से 32 औंस का चौड़े मुँह वाला) मेसन जार लें।","जार में सूखी सामग्री को इस क्रम में परत दर परत रखें: बुइलॉन (यदि उपयोग कर रहे हों), अदरक, राइस नूडल्स, पका बीफ़, मशरूम, शिमला मिर्च, पत्ता गोभी, गाजर, हरा प्याज़ और हरा धनिया। कसकर बंद करें और उपयोग तक फ्रिज में रखें।","एक अलग छोटे डिब्बे में सोया सॉस और नींबू का रस मिलाएँ और फ्रिज में रखें।","जब आप सूप तैयार करने के लिए तैयार हों, तब जार को तैयार करने से कम से कम 15 मिनट पहले फ्रिज से निकाल लें। एक कप गुनगुना पानी (या बीफ़ शोरबा) माइक्रोवेव में उबलने तक गरम करें। सोया सॉस और नींबू का रस मिलाएँ।","पानी और सोया सॉस का मिश्रण जार में डालें और उसे फिर से कसकर बंद करें। नूडल्स के तरल में डूबे होने की पुष्टि करने के लिए जार को हिलाएँ। इसे 2-3 मिनट रखा रहने दें, या जब तक नूडल्स नरम न हो जाएँ। वैकल्पिक रूप से, पानी (या शोरबा) को एक मध्यम सॉसपैन में उबलने तक गरम करें। जार की सामग्री को सॉसपैन में डालें और मिलने और नूडल्स के नरम होने तक चलाएँ। आनंद लेने के लिए कटोरे में डालें।"],[]),
("टोस्ट पर जड़ी-बूटी वाले नरम स्क्रैम्बल्ड अंडे",
"ताज़ी जड़ी-बूटियाँ साधारण स्क्रैम्बल्ड अंडों को कुछ खास बना देती हैं! जो भी जड़ी-बूटियाँ आपके पास हों उनका उपयोग करें, या इनमें से कोई भी दमदार जोड़ी आज़माएँ: अजमोद और पुदीना, डिल और चाइव्स, अजमोद और टैरागन, या पुदीना और तुलसी।\n\nसबसे फूले हुए स्क्रैम्बल्ड अंडों के लिए, उन्हें लगातार चलाने के बजाय धीरे-धीरे मोड़ने की कोशिश करें। आपको बस इतना करना है कि लचीले सिलिकॉन स्पैचुला से फेंटे हुए अंडों को पकते समय धीरे-धीरे एक-एक पंक्ति में खुरचें, और पके हुए अंडे वाले हिस्से को ज़्यादा तरल हिस्से के ऊपर मोड़ें (धीरे से पलटें!)। तब तक जारी रखें जब तक कोई तरल हिस्सा न बचे।",
"2","1 टॉपिंग वाला टोस्ट",
["2 स्लाइस अंकुरित साबुत अनाज या साबुत गेहूँ की ब्रेड","1 छोटा चम्मच ऑलिव ऑयल","2 बड़े अंडे","1/8 छोटा चम्मच नमक","1/4 कप ढीला भरा कटी हुई ताज़ी जड़ी-बूटियाँ"],
["ब्रेड को टोस्टर या टोस्टर ओवन में मनचाहे कुरकुरेपन तक टोस्ट करें।","जब ब्रेड टोस्ट हो रही हो, तब अंडे तैयार करें: एक मध्यम नॉनस्टिक कड़ाही में मध्यम-धीमी आँच पर तेल को अच्छी तरह गरम करें। अंडों को गरम कड़ाही में डालें और मिश्रण को धीरे से चलाते (या मोड़ते) हुए तब तक पकाएँ जब तक अंडे बहने वाले न रहें, लेकिन फिर भी नम हों, लगभग 1 1/2–2 मिनट। कड़ाही को आँच से उतारें, नमक छिड़कें, और जड़ी-बूटियों को धीरे से चलाकर (या मोड़कर) मिलाएँ।","टोस्ट को प्लेटों में रखें। हर टोस्ट पर जड़ी-बूटी वाले अंडों का आधा हिस्सा रखें। चाहें तो स्वादानुसार ताज़ी पिसी काली मिर्च छिड़कें। परोसें।"],[]),
("सौंफ़ कंद, मूली और संतरे का सलाद",
"यह रंग-बिरंगा सलाद चौंकाने वाले स्वादों से भरा है—संतरे की मिठास, सौंफ़ कंद की भरपूरता, और मूली और अरुगुला से थोड़ा-सा मसालेदार स्वाद।",
"6","1 कप",
["2 बड़े चम्मच शैरी विनेगर","2 बड़े चम्मच ऑलिव ऑयल","1 छोटा चम्मच शहद","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 (कुल लगभग 1 1/2 पाउंड) नेवल संतरे (छिले हुए और फाँकों में कटे हुए)","1 बड़ा (लगभग 1 पाउंड) सौंफ़ कंद (आधा किया हुआ, बीच का हिस्सा निकाला हुआ और पतला कटा हुआ)","6 साबुत मूली (पतली कटी हुई)","1/4 कप कटा हुआ ताज़ा पुदीना","5 औंस (लगभग 6 कप) बेबी अरुगुला"],
["एक बड़े कटोरे में सिरका, तेल, शहद, नमक और काली मिर्च को फेंटकर मिलाएँ। संतरे, सौंफ़ कंद, मूली और पुदीना डालें; अच्छी तरह मिलने तक मिलाएँ।","अरुगुला के बिस्तर पर परोसें।"],[]),
("ठंडे मौसम का कॉबलर",
"\"यह क्लासिक एप्पल क्रम्बल पर मेरी अपनी रचना है,\" कुकबुक लेखिका और पोषण विशेषज्ञ केटी कावुटो कहती हैं। \"लेकिन मैं चीनी उँडेलने के बजाय फल की प्राकृतिक मिठास को सम्मान देना चाहती थी। एरोरूट पाउडर इस साबुत फल के भरावन को गाढ़ा करता है और ताज़ा अदरक, दालचीनी और संतरे का छिलका इस मिठाई को दमदार स्वाद देते हैं। और टॉपिंग सिर्फ़ कुरकुरापन से ज़्यादा देती है; ओट्स, साबुत गेहूँ के आटे, कद्दू के बीज, बादाम और मेपल सिरप के साथ, यह आपके पोषक तत्व पाने का स्वादिष्ट तरीका है।\"",
"18","3/4 कप",
["6 मध्यम सेब और/या नाशपाती (छिले, बीच का हिस्सा निकाले और कटे हुए)","1 कप क्रैनबेरी और/या गुठली निकाली चेरी (ताज़ी या जमी हुई)","1 बड़ा चम्मच एरोरूट पाउडर","2 छोटे चम्मच पिसी दालचीनी (बाँटकर उपयोग करें)","1 छोटा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","1 छोटा चम्मच संतरे का छिलका (ताज़ा कद्दूकस किया हुआ)","1 कप बादाम का आटा","2 कप ओल्ड-फ़ैशन्ड रोल्ड ओट्स (ग्लूटेन-मुक्त)","1/2 कप साबुत गेहूँ का आटा","1/4 कप कद्दू के बीज (बिना नमक के, भुने हुए)","1/4 कप बादाम (कच्चे, कटे हुए)","1/4 छोटा चम्मच महीन समुद्री नमक","2 बड़े चम्मच कैनोला ऑयल","1 बड़ा चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","1/3 कप शुद्ध मेपल सिरप (अधिमानतः ग्रेड B)"],
["ओवन को 350°F पर पहले से गरम करें।","भरावन बनाने के लिए, एक मध्यम कटोरे में सारे फल, एरोरूट पाउडर, 1 छोटा चम्मच दालचीनी, अदरक और संतरे का छिलका मिलाएँ। भरावन को 8 x 12 इंच की बेकिंग डिश की तली में फैलाएँ।","टॉपिंग बनाने के लिए, एक अन्य मध्यम कटोरे में बादाम का आटा, ओट्स, आटा, कद्दू के बीज, बादाम, 1 छोटा चम्मच दालचीनी और नमक मिलाएँ। कैनोला ऑयल, ऑलिव ऑयल और मेपल सिरप डालें और बराबर मिलने तक मिलाएँ।","टॉपिंग को भरावन के ऊपर चूरकर डालें और 40 मिनट बेक करें, या जब तक टॉपिंग भूरी न हो जाए और फल में बुलबुले न उठने लगें। कॉबलर को ओवन से निकालें और परोसने से पहले 10 मिनट ठंडा होने के लिए एक तरफ़ रख दें।"],[]),
("संतरा-रोज़मेरी ग्लेज़ वाला सैल्मन और ब्रोकोलिनी",
"ब्रोकोलिनी के साथ यह संतरा रोज़मेरी ग्लेज़ वाला सैल्मन खट्टे, जड़ी-बूटी वाले और नमकीन स्वादों का स्वादिष्ट मेल है। यह सेहतमंद और सुरुचिपूर्ण व्यंजन है जो सप्ताह के किसी भी दिन के आसान रात के खाने के लिए एकदम सही है।",
"4","1, 6 औंस का फ़िले + 1/2 गुच्छा ब्रोकोलिनी",
["2 गुच्छे ब्रोकोलिनी (कुल 1 पाउंड)","1 बड़ा चम्मच ऑलिव ऑयल","4 साबुत सैल्मन फ़िले (हर एक 6 औंस)","1 बड़ा चम्मच संतरे का छिलका","1/2 कप ताज़ा संतरे का रस (लगभग 2 संतरों का रस)","1/2 कप कम सोडियम वाला चिकन शोरबा","1 बड़ा चम्मच + 2 छोटे चम्मच ब्राउन शुगर का विकल्प","3 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच कॉर्नस्टार्च","1 बड़ा चम्मच ताज़ी रोज़मेरी (बारीक कटी हुई)","2 छोटे चम्मच साबुत अलसी के बीज","1/4 छोटा चम्मच कोशर नमक","1/8 छोटा चम्मच काली मिर्च"],
["ओवन को 400°F पर पहले से गरम करें। बेकिंग शीट पर चर्मपत्र कागज़ या फ़ॉइल बिछाएँ।","ब्रोकोलिनी को बेकिंग शीट के एक तरफ़ रखें और ऊपर से ऑलिव ऑयल डालें।","सैल्मन को पेपर टॉवल से थपथपाकर सुखाएँ और बेकिंग शीट के दूसरे तरफ़ रखें।","संतरे का छिलका, संतरे का रस, शोरबा, ब्राउन शुगर का विकल्प, लहसुन, रोज़मेरी, कॉर्नस्टार्च और अलसी के बीज एक छोटे सॉसपैन में मध्यम आँच पर मिलाएँ। बीच-बीच में फेंटते हुए तब तक पकाएँ जब तक सॉस आधा न रह जाए और गाढ़ा न हो जाए, 8–10 मिनट। यह चम्मच से चिपकना चाहिए।","सॉस को सैल्मन पर लगाएँ। बेकिंग शीट को ओवन में रखें और सैल्मन के अंदर का तापमान 145°F होने और ब्रोकोलिनी के नरम होने तक, 6–10 मिनट बेक करें। नमक और काली मिर्च डालें।"],[]),
("क्विनोआ, पालक और हमस वाले अंडे की सफ़ेदी के रैप",
"अंडे की सफ़ेदी के ये रैप पारंपरिक नाश्ते के रैप का ताज़ा और पेट भरने वाला विकल्प हैं, जिनमें जड़ी-बूटी वाला क्विनोआ और पालक का मिश्रण मलाईदार हमस और रसीले टमाटर के साथ है। रैप के रूप में अंडे की सफ़ेदी का उपयोग भोजन को कार्बोहाइड्रेट और संतृप्त वसा में कम रखता है। यह संतुलित विकल्प है जो रक्त ग्लूकोज़ (ब्लड शुगर) के प्रबंधन में मदद करता है और भरपूर स्वाद और बनावट भी देता है। यह कम वसा वाली और भूमध्यसागरीय रेसिपी है।",
"2","1 रैप",
["1/2 कप क्विनोआ","1 कप अंडे की सफ़ेदी","1/8 छोटा चम्मच नमक","1/4 कप ताज़े चाइव्स (बारीक कटे हुए)","2 कप बेबी पालक","1 कप चपटी पत्ती वाला अजमोद (पत्तियाँ)","1 नॉनस्टिक कुकिंग स्प्रे","2 बड़े चम्मच हमस","1 साबुत टमाटर (पतला कटा हुआ)"],
["क्विनोआ को ठंडे पानी से धो लें।","एक मध्यम सॉसपैन में 1 कप पानी उबालें। क्विनोआ डालें, आँच धीमी करें, ढक दें और लगभग 15 मिनट, या पानी के सोखे जाने तक धीमी आँच पर पकाएँ। आँच से उतारें और ढककर 5 मिनट रखा रहने दें। काँटे से फुलाएँ।","एक कटोरे में अंडे की सफ़ेदी, नमक और कटे चाइव्स को फेंटकर मिलाएँ।","10 इंच की नॉनस्टिक कड़ाही को मध्यम-धीमी आँच पर गरम करें और हल्का नॉनस्टिक कुकिंग स्प्रे लगाएँ।","आधा अंडे का मिश्रण कड़ाही में डालें, तली को बराबर ढकने के लिए घुमाएँ। तब तक पकाएँ जब तक तली बस जम न जाए और ऊपरी हिस्सा थोड़ा नम रहे, लगभग 3–4 मिनट। रैप को सावधानी से पलटें और 10 सेकंड और पकाएँ। प्लेट में निकालें और बचे अंडे के मिश्रण के साथ दोहराएँ।","फ़ूड प्रोसेसर में बेबी पालक और अजमोद की पत्तियाँ मिलाएँ। बारीक कटने तक पल्स करें। पके हुए क्विनोआ में धीरे से मिलाएँ।","जोड़ने के लिए, हर अंडे के रैप को साफ़ सतह पर सपाट बिछाएँ। हर रैप के आधे हिस्से पर एक भरपूर बड़ा चम्मच नींबू वाला हमस फैलाएँ। हमस के ऊपर आधा क्विनोआ का मिश्रण चम्मच से डालें, चिपकाने के लिए हल्के से दबाएँ। ऊपर टमाटर के स्लाइस रखें। रैप को भरावन के ऊपर आधा मोड़ें, फिर चौथाई मोड़ बनाने के लिए एक बार और मोड़ें।"],[]),
("मक्का और तोरी के टैकोज़",
"ये शाकाहारी टैकोज़ गर्मियों की ताज़ी सब्ज़ियों से भरे हैं। आपके पास पड़ी किसी भी अतिरिक्त सब्ज़ी के उपयोग का यह बढ़िया तरीका है, और आप अपने फ्रिज में मौजूद अन्य सब्ज़ियाँ भी डाल सकते हैं।",
"6","1 टैको",
["1 बड़ा चम्मच ऑलिव ऑयल (बाँटकर)","3 मध्यम भुट्टे (छिलका उतारे और दाने भुट्टे से काटे हुए; भुट्टे फेंक दें)","1/4 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच पिसा जीरा","1/2 कप मीठा प्याज़ (बहुत बारीक कटा हुआ)","1 मध्यम तोरी/ज़ुकीनी (बिना छिली और 1/2 इंच के टुकड़ों में कटी हुई)","2 मध्यम टमाटर (बीज निकाले और 1/2 इंच के टुकड़ों में कटे हुए)","1 बड़ा चम्मच ताज़ा ओरेगानो (बारीक कटा हुआ)","6 छोटी मक्के की टॉर्टिला","1/4 कप सादा बिना वसा वाला ग्रीक योगर्ट","1/2 कप सालसा"],
["एक बड़ी कड़ाही में मध्यम आँच पर 2 छोटे चम्मच तेल गरम करें। मक्के के दाने डालें और 3 मिनट भूनें। जीरा और चिली पाउडर डालें और 2 मिनट भूनें। मक्के के मिश्रण को कड़ाही से निकाल लें।","बचा हुआ ऑलिव ऑयल कड़ाही में डालें और प्याज़ डालें। प्याज़ को 5 मिनट, नरम होने तक भूनें। तोरी डालें और 3 मिनट भूनें। टमाटर डालें और 2 मिनट भूनें। ओरेगानो डालें और 1 मिनट भूनें; अलग रखा मक्के का मिश्रण मिलाएँ।","मक्के के मिश्रण को गरम की हुई टॉर्टिला में बाँटें और हर टैको के ऊपर 2 छोटे चम्मच योगर्ट और 2 छोटे चम्मच सालसा क्रूडा डालें।","रसोइये का सुझाव: ताज़े मक्के को तैयार करने के लिए अपने माइक्रोवेव का उपयोग करें! हर भुट्टे से, डंठल वाले सिरे का लगभग 1 इंच काट दें। एक बार में 3 भुट्टे तक माइक्रोवेव-सुरक्षित डिब्बे में डालें और हाई पर 6 मिनट माइक्रोवेव करें। भुट्टों को माइक्रोवेव से निकालें और पकड़ने लायक ठंडा होने दें। छिलके को पकड़कर, धीरे से दबाएँ और हिलाएँ, और मक्का एक ही बार में बाहर निकल आएगा। अगर कोई रेशे बचे रहें, तो रेशे हटाने के लिए भुट्टे को पेपर टॉवल से ऊपर-नीचे रगड़ें।"],[]),
]
